CREATE TABLE `Connection` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `residentId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tower` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `floor` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `flatNo` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unitType` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unitArea` int NOT NULL,
  `meterNo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sanctionedLoad` decimal(65,30) NOT NULL,
  `status` enum('ACTIVE','INACTIVE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `connectedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY `Connection_flatNo_key` (`flatNo`),
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `Connection_residentId_fkey` (`residentId`),
  CONSTRAINT `Connection_residentId_fkey` FOREIGN KEY (`residentId`) REFERENCES `Resident` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
